// Common types, error handling and small utilities.
#pragma once

#include <cstdint>
#include <cstddef>
#include <cstring>
#include <cstdlib>
#include <string>
#include <vector>
#include <memory>

typedef uint8_t  Byte;
typedef uint16_t UInt16;
typedef uint32_t UInt32;
typedef uint64_t UInt64;
typedef int32_t  Int32;
typedef int64_t  Int64;

// Result codes.  They mirror the granularity that 7-Zip's messages need.
enum ErrKind {
  ERR_OK = 0,
  ERR_DATA,             // "Data error"
  ERR_CRC,              // "CRC failed"
  ERR_UNEXPECTED_END,   // "Unexpected end of data"
  ERR_UNSUPPORTED,      // "Unsupported method"
  ERR_HEADERS,          // "Headers Error"
  ERR_PASSWORD,         // wrong password
  ERR_NOT_ARCHIVE,      // "Is not archive"
  ERR_NOTIMPL,          // E_NOTIMPL
  ERR_MEMORY,           // E_OUTOFMEMORY
  ERR_FAIL,             // E_FAIL
  ERR_SYSTEM,           // errno based
  ERR_USER,             // command line error
  ERR_ABORT             // user break
};

struct Exc {
  ErrKind kind;
  std::string msg;      // optional extra text
  int sysErrno;
  Exc(ErrKind k) : kind(k), sysErrno(0) {}
  Exc(ErrKind k, const std::string &m) : kind(k), msg(m), sysErrno(0) {}
};

inline void ThrowData()       { throw Exc(ERR_DATA); }
inline void ThrowCrc()        { throw Exc(ERR_CRC); }
inline void ThrowEnd()        { throw Exc(ERR_UNEXPECTED_END); }
inline void ThrowUnsup()      { throw Exc(ERR_UNSUPPORTED); }
inline void ThrowHeaders()    { throw Exc(ERR_HEADERS); }
inline void ThrowMem()        { throw Exc(ERR_MEMORY); }
inline void ThrowNotImpl()    { throw Exc(ERR_NOTIMPL); }
inline void ThrowFail()       { throw Exc(ERR_FAIL); }
inline void ThrowUser(const std::string &m) { throw Exc(ERR_USER, m); }

// ---------------------------------------------------------------- byte access

inline UInt16 GetUi16(const Byte *p) { UInt16 v; memcpy(&v, p, 2); return v; }
inline UInt32 GetUi32(const Byte *p) { UInt32 v; memcpy(&v, p, 4); return v; }
inline UInt64 GetUi64(const Byte *p) { UInt64 v; memcpy(&v, p, 8); return v; }
inline void SetUi16(Byte *p, UInt16 v) { memcpy(p, &v, 2); }
inline void SetUi32(Byte *p, UInt32 v) { memcpy(p, &v, 4); }
inline void SetUi64(Byte *p, UInt64 v) { memcpy(p, &v, 8); }

inline UInt16 GetBe16(const Byte *p) { return (UInt16)(((UInt32)p[0] << 8) | p[1]); }
inline UInt32 GetBe32(const Byte *p) {
  return ((UInt32)p[0] << 24) | ((UInt32)p[1] << 16) | ((UInt32)p[2] << 8) | p[3];
}
inline UInt64 GetBe64(const Byte *p) { return ((UInt64)GetBe32(p) << 32) | GetBe32(p + 4); }
inline void SetBe32(Byte *p, UInt32 v) {
  p[0] = (Byte)(v >> 24); p[1] = (Byte)(v >> 16); p[2] = (Byte)(v >> 8); p[3] = (Byte)v;
}
inline void SetBe64(Byte *p, UInt64 v) { SetBe32(p, (UInt32)(v >> 32)); SetBe32(p + 4, (UInt32)v); }

// ---------------------------------------------------------------- containers

typedef std::vector<Byte> ByteBuf;

// A growable output buffer with a cheap append.
struct DynBuf {
  ByteBuf v;
  void add(const void *p, size_t n) {
    const Byte *s = (const Byte *)p;
    v.insert(v.end(), s, s + n);
  }
  void addByte(Byte b) { v.push_back(b); }
  size_t size() const { return v.size(); }
  Byte *data() { return v.empty() ? nullptr : &v[0]; }
  const Byte *data() const { return v.empty() ? nullptr : &v[0]; }
};

// ---------------------------------------------------------------- strings

typedef std::string AString;
// Unicode strings are held as UTF-8 everywhere; conversion helpers live in
// unicode.cpp for the UTF-16 on-disk formats.
typedef std::string UString;

std::string Utf16ToUtf8(const UInt16 *src, size_t len);
void Utf8ToUtf16(const std::string &src, std::vector<UInt16> &dest);

bool StrEqNoCase(const char *a, const char *b);
bool StrEqNoCase(const std::string &a, const char *b);
std::string ToLower(const std::string &s);
std::string ToUpper(const std::string &s);

