// Stream abstractions used by every codec and archive handler.
#pragma once

#include "common.h"
#include <cstdio>

// Progress reporting hook. Codecs call it so the UI can print percentages.
struct IProgress {
  virtual ~IProgress() {}
  // inSize/outSize are cumulative for the current operation; either may be
  // (UInt64)-1 when unknown.
  virtual void SetRatioInfo(UInt64 inSize, UInt64 outSize) = 0;
};

struct ISeqInStream {
  virtual ~ISeqInStream() {}
  // Reads up to len bytes.  Returns the number read; a short read (including
  // 0) means end of stream.
  virtual size_t Read(Byte *buf, size_t len) = 0;
  // Reads exactly len bytes or throws ERR_UNEXPECTED_END.
  void ReadFull(Byte *buf, size_t len);
  // Reads exactly len bytes, returns false on immediate EOF.
  bool ReadFullOrEof(Byte *buf, size_t len);
  Byte ReadByte() { Byte b; ReadFull(&b, 1); return b; }
  void Skip(UInt64 len);
};

struct ISeqOutStream {
  virtual ~ISeqOutStream() {}
  virtual void Write(const Byte *buf, size_t len) = 0;
  void WriteByte(Byte b) { Write(&b, 1); }
};

// ------------------------------------------------------------- memory streams

struct MemInStream : ISeqInStream {
  const Byte *p; size_t size, pos;
  MemInStream(const Byte *d, size_t n) : p(d), size(n), pos(0) {}
  MemInStream(const ByteBuf &b) : p(b.empty() ? nullptr : &b[0]), size(b.size()), pos(0) {}
  size_t Read(Byte *buf, size_t len) override {
    size_t n = size - pos;
    if (n > len) n = len;
    if (n) memcpy(buf, p + pos, n);
    pos += n;
    return n;
  }
};

struct MemOutStream : ISeqOutStream {
  ByteBuf buf;
  void Write(const Byte *b, size_t len) override { buf.insert(buf.end(), b, b + len); }
};

// Discards everything, counting the size.
struct NullOutStream : ISeqOutStream {
  UInt64 total = 0;
  void Write(const Byte *, size_t len) override { total += len; }
};

// ------------------------------------------------------------- file streams

struct FileInStream : ISeqInStream {
  FILE *f = nullptr;
  bool owned = false;
  UInt64 pos = 0;
  ~FileInStream() { Close(); }
  bool Open(const std::string &path);
  void AttachStdin();
  void Close();
  size_t Read(Byte *buf, size_t len) override;
  bool Seek(UInt64 off);
  UInt64 GetSize();
};

struct FileOutStream : ISeqOutStream {
  FILE *f = nullptr;
  bool owned = false;
  UInt64 pos = 0;
  ~FileOutStream() { Close(); }
  bool Create(const std::string &path);
  void AttachStdout();
  void Close();
  void Write(const Byte *buf, size_t len) override;
};

// ------------------------------------------------------------ wrapper streams

// Limits how much can be read from the underlying stream.
struct LimitedInStream : ISeqInStream {
  ISeqInStream *base; UInt64 rem;
  LimitedInStream(ISeqInStream *b, UInt64 n) : base(b), rem(n) {}
  size_t Read(Byte *buf, size_t len) override {
    if (len > rem) len = (size_t)rem;
    if (len == 0) return 0;
    size_t n = base->Read(buf, len);
    rem -= n;
    return n;
  }
};

// Counts bytes and optionally reports progress.
struct CountInStream : ISeqInStream {
  ISeqInStream *base; UInt64 total = 0;
  CountInStream(ISeqInStream *b) : base(b) {}
  size_t Read(Byte *buf, size_t len) override {
    size_t n = base->Read(buf, len);
    total += n;
    return n;
  }
};

struct CountOutStream : ISeqOutStream {
  ISeqOutStream *base; UInt64 total = 0;
  CountOutStream(ISeqOutStream *b) : base(b) {}
  void Write(const Byte *buf, size_t len) override {
    if (base) base->Write(buf, len);
    total += len;
  }
};

// Stops after outSize bytes have been produced; extra data is dropped.
struct LimitedOutStream : ISeqOutStream {
  ISeqOutStream *base; UInt64 rem;
  LimitedOutStream(ISeqOutStream *b, UInt64 n) : base(b), rem(n) {}
  void Write(const Byte *buf, size_t len) override {
    if (len > rem) len = (size_t)rem;
    if (len) { base->Write(buf, len); rem -= len; }
  }
};

// Buffered reader used by the header parsers.
struct BufferedIn {
  ISeqInStream *base;
  ByteBuf buf;
  size_t pos = 0, filled = 0;
  BufferedIn(ISeqInStream *b, size_t cap = 1 << 16) : base(b), buf(cap) {}
  int PeekByte() {
    if (pos == filled) {
      pos = filled = 0;
      filled = base->Read(&buf[0], buf.size());
      if (filled == 0) return -1;
    }
    return buf[pos];
  }
  int GetByte() { int c = PeekByte(); if (c >= 0) pos++; return c; }
};

void CopyStream(ISeqInStream &in, ISeqOutStream &out, UInt64 *limit, IProgress *progress);

