// Codec (coder) interface and registry.
#pragma once

#include "common.h"
#include "stream.h"

// Method IDs as used by the 7z container.
namespace MethodID {
  const UInt64 kCopy       = 0x00;
  const UInt64 kDelta      = 0x03;
  const UInt64 kARM64      = 0x0a;
  const UInt64 kRISCV      = 0x0b;
  const UInt64 kSwap2      = 0x020302;
  const UInt64 kSwap4      = 0x020304;
  const UInt64 kLZMA2      = 0x21;
  const UInt64 kLZMA       = 0x030101;
  const UInt64 kPPMD       = 0x030401;
  const UInt64 kBCJ        = 0x03030103;
  const UInt64 kPPC        = 0x03030205;
  const UInt64 kIA64       = 0x03030401;
  const UInt64 kARM        = 0x03030501;
  const UInt64 kARMT       = 0x03030701;
  const UInt64 kSPARC      = 0x03030805;
  const UInt64 kBCJ2       = 0x0303011b;
  const UInt64 kDeflate    = 0x040108;
  const UInt64 kDeflate64  = 0x040109;
  const UInt64 kBZip2      = 0x040202;
  const UInt64 kZSTD       = 0x4f71101;
  const UInt64 k7zAES      = 0x06f10701;
  const UInt64 kAES256CBC  = 0x06f00181;
}

struct CoderProps {
  // Raw property bytes from the archive (decoder side).
  ByteBuf props;
  // Encoder-side parameters.
  UInt32 level = 5;
  UInt32 dictSize = 0;
  UInt32 numFastBytes = 0;
  UInt32 lc = 0xFF, lp = 0xFF, pb = 0xFF;
  UInt32 numThreads = 1;
  UInt32 mem = 0;        // PPMd memory
  UInt32 order = 0;      // PPMd order
  UInt32 algo = 0xFF;
  UInt32 mf = 0;         // match finder id
  UInt64 reduceSize = (UInt64)(Int64)-1;
  UInt32 delta = 1;
  UInt32 passes = 0;
  ByteBuf key, iv;
};

// A coder transforms one input stream into one output stream.
struct ICoder {
  virtual ~ICoder() {}
  // inSize/outSize may be null when unknown.  Implementations must stop after
  // outSize bytes when it is known.
  virtual void Code(ISeqInStream &in, ISeqOutStream &out,
                    const UInt64 *inSize, const UInt64 *outSize,
                    IProgress *progress) = 0;
  // Property bytes an encoder wants recorded in the container.
  virtual void GetProps(ByteBuf &out) { out.clear(); }
};

// Coders with more than one input (BCJ2 decode) or output (BCJ2 encode).
struct IMultiCoder {
  virtual ~IMultiCoder() {}
  virtual void Code(std::vector<ISeqInStream *> &in, std::vector<ISeqOutStream *> &out,
                    const UInt64 *outSize, IProgress *progress) = 0;
};

// ---- factories ------------------------------------------------------------

ICoder *CreateDecoder(UInt64 id, const CoderProps &p);
ICoder *CreateEncoder(UInt64 id, const CoderProps &p);
IMultiCoder *CreateMultiDecoder(UInt64 id, const CoderProps &p);
IMultiCoder *CreateMultiEncoder(UInt64 id, const CoderProps &p);
bool IsFilterMethod(UInt64 id);
// Number of in/out streams for a method (1 unless BCJ2).
void GetMethodStreamCounts(UInt64 id, unsigned &numIn, unsigned &numOut);

// ---- individual codecs ----------------------------------------------------

ICoder *CreateCopyCoder();

ICoder *CreateLzmaDecoder(const CoderProps &p);
ICoder *CreateLzmaEncoder(const CoderProps &p);
ICoder *CreateLzma2Decoder(const CoderProps &p);
ICoder *CreateLzma2Encoder(const CoderProps &p);

ICoder *CreateDeflateDecoder(bool deflate64);
ICoder *CreateDeflateEncoder(const CoderProps &p);

ICoder *CreateBZip2Decoder(const CoderProps &p);
ICoder *CreateBZip2Encoder(const CoderProps &p);

ICoder *CreatePpmdDecoder(const CoderProps &p);
ICoder *CreatePpmdEncoder(const CoderProps &p);

ICoder *CreateZstdDecoder();

ICoder *CreateDeltaCoder(unsigned delta, bool encode);
ICoder *CreateBranchCoder(UInt64 id, const CoderProps &p, bool encode);
IMultiCoder *CreateBcj2Decoder();
IMultiCoder *CreateBcj2Encoder(const CoderProps &p);

ICoder *CreateAesCoder(bool encode, bool isZipCrypto7z, const CoderProps &p);

