#include "stream.h"
#include <unistd.h>
#include <sys/stat.h>
#include <cerrno>

void ISeqInStream::ReadFull(Byte *buf, size_t len) {
  while (len) {
    size_t n = Read(buf, len);
    if (n == 0) ThrowEnd();
    buf += n; len -= n;
  }
}

bool ISeqInStream::ReadFullOrEof(Byte *buf, size_t len) {
  size_t got = 0;
  while (got < len) {
    size_t n = Read(buf + got, len - got);
    if (n == 0) {
      if (got == 0) return false;
      ThrowEnd();
    }
    got += n;
  }
  return true;
}

void ISeqInStream::Skip(UInt64 len) {
  Byte tmp[4096];
  while (len) {
    size_t want = (size_t)(len < sizeof(tmp) ? len : sizeof(tmp));
    size_t n = Read(tmp, want);
    if (n == 0) ThrowEnd();
    len -= n;
  }
}

// ---------------------------------------------------------------- file input

bool FileInStream::Open(const std::string &path) {
  Close();
  f = fopen(path.c_str(), "rb");
  if (!f) return false;
  owned = true;
  pos = 0;
  return true;
}

void FileInStream::AttachStdin() { Close(); f = stdin; owned = false; pos = 0; }

void FileInStream::Close() {
  if (f && owned) fclose(f);
  f = nullptr; owned = false;
}

size_t FileInStream::Read(Byte *buf, size_t len) {
  if (!f || len == 0) return 0;
  size_t n = fread(buf, 1, len, f);
  if (n == 0 && ferror(f)) {
    Exc e(ERR_SYSTEM); e.sysErrno = errno; throw e;
  }
  pos += n;
  return n;
}

bool FileInStream::Seek(UInt64 off) {
  if (!f) return false;
  if (fseeko(f, (off_t)off, SEEK_SET) != 0) return false;
  pos = off;
  return true;
}

UInt64 FileInStream::GetSize() {
  if (!f) return 0;
  off_t cur = ftello(f);
  if (fseeko(f, 0, SEEK_END) != 0) return 0;
  off_t end = ftello(f);
  fseeko(f, cur, SEEK_SET);
  return (UInt64)end;
}

// --------------------------------------------------------------- file output

bool FileOutStream::Create(const std::string &path) {
  Close();
  f = fopen(path.c_str(), "wb");
  if (!f) return false;
  owned = true;
  pos = 0;
  return true;
}

void FileOutStream::AttachStdout() { Close(); f = stdout; owned = false; pos = 0; }

void FileOutStream::Close() {
  if (f && owned) fclose(f);
  else if (f) fflush(f);
  f = nullptr; owned = false;
}

void FileOutStream::Write(const Byte *buf, size_t len) {
  if (!f || len == 0) return;
  size_t n = fwrite(buf, 1, len, f);
  if (n != len) {
    Exc e(ERR_SYSTEM); e.sysErrno = errno; throw e;
  }
  pos += len;
}

// -------------------------------------------------------------------- helpers

void CopyStream(ISeqInStream &in, ISeqOutStream &out, UInt64 *limit, IProgress *progress) {
  std::vector<Byte> buf(1 << 16);
  UInt64 total = 0;
  for (;;) {
    size_t want = buf.size();
    if (limit) {
      UInt64 rem = *limit - total;
      if (rem == 0) break;
      if (rem < want) want = (size_t)rem;
    }
    size_t n = in.Read(&buf[0], want);
    if (n == 0) {
      if (limit) ThrowEnd();
      break;
    }
    out.Write(&buf[0], n);
    total += n;
    if (progress) progress->SetRatioInfo(total, total);
  }
}

