// Archive abstraction shared by every format handler.
#pragma once

#include "common.h"
#include "stream.h"
#include <utility>

// ---------------------------------------------------------------- properties

typedef std::vector<std::pair<std::string, std::string> > PropList;

// FILETIME: 100ns ticks since 1601-01-01.
const UInt64 kFileTimeUnixEpoch = 116444736000000000ULL;

// Windows file attribute bits we care about.
const UInt32 FA_READONLY  = 0x0001;
const UInt32 FA_HIDDEN    = 0x0002;
const UInt32 FA_SYSTEM    = 0x0004;
const UInt32 FA_DIRECTORY = 0x0010;
const UInt32 FA_ARCHIVE   = 0x0020;
const UInt32 FA_DEVICE    = 0x0040;
const UInt32 FA_NORMAL    = 0x0080;
const UInt32 FA_TEMPORARY = 0x0100;
const UInt32 FA_SPARSE    = 0x0200;
const UInt32 FA_REPARSE   = 0x0400;
const UInt32 FA_COMPRESSED= 0x0800;
const UInt32 FA_OFFLINE   = 0x1000;
const UInt32 FA_NOT_INDEXED = 0x2000;
const UInt32 FA_ENCRYPTED = 0x4000;
const UInt32 FA_UNIX_EXT  = 0x8000;   // 7-Zip: high 16 bits hold the unix mode

// ---------------------------------------------------------------- items

struct ArcItem {
  std::string path;            // '/' separated, as stored
  bool isDir = false;
  bool hasStream = true;       // false for dirs and (in 7z) empty files
  UInt64 size = 0;
  UInt64 packSize = 0;
  bool sizeDefined = true;
  bool packSizeDefined = false;
  bool crcDefined = false;
  UInt32 crc = 0;
  UInt64 mtime = 0; bool mtimeDefined = false;
  UInt64 atime = 0; bool atimeDefined = false;
  UInt64 ctime = 0; bool ctimeDefined = false;
  UInt32 attrib = 0; bool attribDefined = false;
  bool encrypted = false;
  bool isSymLink = false;
  bool isHardLink = false;
  std::string linkTarget;
  std::string method;          // rendered method string for this item
  Int64 blockIndex = -1;       // folder index, -1 = none
  std::string comment; bool commentDefined = false;
  std::string hostOS; bool hostOSDefined = false;
  UInt32 unixMode() const { return attrib >> 16; }
};

// Result of extracting one item.
enum OpResult {
  OP_OK = 0,
  OP_UNSUPPORTED_METHOD,
  OP_DATA_ERROR,
  OP_CRC_ERROR,
  OP_UNAVAILABLE,
  OP_UNEXPECTED_END,
  OP_DATA_AFTER_END,
  OP_IS_NOT_ARC,
  OP_HEADERS_ERROR,
  OP_WRONG_PASSWORD
};

struct IExtractCallback {
  virtual ~IExtractCallback() {}
  // Returns the destination for the item, or null to discard the data.
  virtual ISeqOutStream *GetStream(size_t index) = 0;
  // Called after the item's data has been fully written (stream released).
  virtual void ReleaseStream(size_t index) {}
  virtual void SetOperationResult(size_t index, OpResult res) = 0;
  virtual void SetTotal(UInt64 total) {}
  virtual void SetCompleted(UInt64 done) {}
  virtual std::string GetPassword() { return std::string(); }
  virtual bool HasPassword() { return false; }
};

// -------------------------------------------------------------- open callback

struct OpenResultInfo {
  bool isArc = false;
  bool errorFlagged = false;      // opened but with errors
  std::string warning;
  UInt64 physSize = 0; bool physSizeDefined = false;
  UInt64 offset = 0;              // bytes skipped before the archive start
  UInt64 tailSize = 0;            // bytes after the payload
};

struct IInArchive {
  virtual ~IInArchive() {}
  // Throws on failure.  `stream` must stay alive for the archive's lifetime.
  virtual void Open(FileInStream *stream, const std::string &path) = 0;
  virtual size_t NumItems() const = 0;
  virtual const ArcItem &Item(size_t i) const = 0;
  // Archive-level properties for the `l` header block and -slt.
  virtual void GetArcProps(PropList &props) = 0;
  virtual const char *FormatName() const = 0;
  // indices empty means "all items".
  virtual void Extract(const std::vector<size_t> &indices, bool testMode,
                       IExtractCallback *cb) = 0;
  virtual bool IsSolid() const { return false; }
  virtual UInt64 GetPhysSize() const { return 0; }
  virtual UInt64 GetHeadersSize() const { return 0; }
  virtual bool HeadersSizeDefined() const { return false; }
  virtual std::string GetItemProp(size_t i, const char *name) { return std::string(); }
  // Extra -slt property lines appended per item by some formats.
  virtual void GetItemProps(size_t i, PropList &props) {}
  OpenResultInfo openInfo;
};

// ------------------------------------------------------------------- updating

struct IUpdateCallback;

struct UpdateItem {
  bool newData = false;
  bool newProps = false;
  Int64 indexInArchive = -1;   // source item when copying
  Int64 indexInClient = -1;    // index into the caller's file list
  ArcItem props;               // used when newProps
};

struct IUpdateCallback {
  virtual ~IUpdateCallback() {}
  // Opens the disk file for items[indexInClient]; returns null for empty items.
  virtual ISeqInStream *GetStream(Int64 indexInClient) = 0;
  virtual void ReleaseStream(Int64 indexInClient) {}
  virtual void SetOperationResult(Int64 indexInClient) {}
  virtual void SetTotal(UInt64 size) {}
  virtual void SetCompleted(UInt64 done) {}
  virtual std::string GetPassword() { return std::string(); }
  virtual bool HasPassword() { return false; }
};

// Encoder configuration parsed from -m switches.
struct MethodProp {
  std::string name;    // e.g. "0", "x", "d", "mt"
  std::string value;
};

struct EncodeParams {
  UInt32 level = 5;
  bool levelDefined = false;
  std::vector<MethodProp> props;      // in switch order
  bool solidDefined = false;
  bool solid = true;
  UInt64 solidBlockSize = (UInt64)(Int64)-1;
  UInt64 solidFiles = (UInt64)(Int64)-1;
  bool solidExtension = false;
  bool compressHeader = true;
  bool encryptHeader = false;
  bool encryptHeaderDefined = false;
  UInt32 numThreads = 1;
  bool numThreadsDefined = false;
  std::string password;
  bool passwordDefined = false;
  bool storeTimeM = true, storeTimeA = false, storeTimeC = false;
  bool timeMDefined = false, timeADefined = false, timeCDefined = false;
  UInt32 timePrec = 0; bool timePrecDefined = false;
  bool storeSymLinks = false;
  bool storeHardLinks = false;
  bool storeOwner = false;
  std::string zipEncryptionMethod;
  // Raw -m list for formats that want to interpret extras themselves.
  const MethodProp *Find(const char *n) const {
    for (size_t i = props.size(); i-- > 0;)
      if (StrEqNoCase(props[i].name, n)) return &props[i];
    return nullptr;
  }
};

struct IOutArchive {
  virtual ~IOutArchive() {}
  virtual void SetParams(const EncodeParams &p) = 0;
  virtual void UpdateItems(ISeqOutStream *out, std::vector<UpdateItem> &items,
                           IUpdateCallback *cb, IInArchive *inArc) = 0;
};

