  const char *name;
  const char *extensions;       // space separated, may contain "(.tar)" markers
  const char *flags;            // the 23-char string printed by `i`
  const char *signatureText;    // as printed by `i`
  bool updateSupported;
  IInArchive *(*createIn)();
  IOutArchive *(*createOut)();
  // Signature match: returns true if the buffer looks like this format.
  bool (*isArc)(const Byte *p, size_t size);
  int signatureOffset;
};

const std::vector<FormatInfo> &GetFormats();
