#include "fs.h"

#include <sys/stat.h>
#include <sys/types.h>
#include <dirent.h>
#include <unistd.h>
#include <utime.h>
#include <fcntl.h>
#include <cerrno>
#include <ctime>
#include <algorithm>

UInt64 UnixTimeToFileTime(Int64 sec, long nsec) {
  Int64 v = sec * 10000000LL + (Int64)kFileTimeUnixEpoch2 + nsec / 100;
  if (v < 0) v = 0;
  return (UInt64)v;
}

void FileTimeToUnix(UInt64 ft, Int64 &sec, long &nsec) {
  Int64 v = (Int64)ft - (Int64)kFileTimeUnixEpoch2;
  sec = v / 10000000LL;
  Int64 rem = v % 10000000LL;
  if (rem < 0) { rem += 10000000LL; sec--; }
  nsec = (long)(rem * 100);
}

static UInt32 ModeToAttrib(mode_t mode, bool isDir) {
  UInt32 a = FA_UNIX_EXT | ((UInt32)mode << 16);
  if (isDir) a |= FA_DIRECTORY;
  else a |= FA_ARCHIVE;
  if (!(mode & S_IWUSR)) a |= FA_READONLY;
  return a;
}

bool GetDiskFileInfo(const std::string &path, DiskFileInfo &fi, bool followLinks) {
  struct stat st;
  int r = followLinks ? stat(path.c_str(), &st) : lstat(path.c_str(), &st);
  fi.path = path;
  {
    std::string d, n;
    SplitPath(path, d, n);
    fi.name = n;
  }
  if (r != 0) { fi.exists = false; return false; }
  fi.exists = true;
  fi.isDir = S_ISDIR(st.st_mode) != 0;
  fi.isSymLink = S_ISLNK(st.st_mode) != 0;
  fi.isSpecial = !fi.isDir && !fi.isSymLink && !S_ISREG(st.st_mode);
  fi.size = fi.isDir ? 0 : (UInt64)st.st_size;
  fi.mode = (UInt32)st.st_mode;
  fi.attrib = ModeToAttrib(st.st_mode, fi.isDir);
  fi.uid = (UInt32)st.st_uid;
  fi.gid = (UInt32)st.st_gid;
  fi.nLinks = (UInt64)st.st_nlink;
  fi.inode = (UInt64)st.st_ino;
  fi.dev = (UInt64)st.st_dev;
#if defined(__linux__)
  fi.mtime = UnixTimeToFileTime(st.st_mtim.tv_sec, st.st_mtim.tv_nsec);
  fi.atime = UnixTimeToFileTime(st.st_atim.tv_sec, st.st_atim.tv_nsec);
  fi.ctime = UnixTimeToFileTime(st.st_ctim.tv_sec, st.st_ctim.tv_nsec);
#else
  fi.mtime = UnixTimeToFileTime(st.st_mtime, 0);
  fi.atime = UnixTimeToFileTime(st.st_atime, 0);
  fi.ctime = UnixTimeToFileTime(st.st_ctime, 0);
#endif
  return true;
}

bool ReadSymLink(const std::string &path, std::string &target) {
  char buf[4096];
  ssize_t n = readlink(path.c_str(), buf, sizeof(buf) - 1);
  if (n < 0) return false;
  target.assign(buf, (size_t)n);
  return true;
}

bool ListDirectory(const std::string &dir, std::vector<std::string> &names) {
  names.clear();
  DIR *d = opendir(dir.empty() ? "." : dir.c_str());
  if (!d) return false;
  struct dirent *e;
  while ((e = readdir(d)) != nullptr) {
    if (e->d_name[0] == '.' && (e->d_name[1] == 0 ||
        (e->d_name[1] == '.' && e->d_name[2] == 0)))
      continue;
    names.push_back(e->d_name);
  }
  closedir(d);
  std::sort(names.begin(), names.end());
  return true;
}

bool CreateComplexDir(const std::string &path) {
  if (path.empty()) return true;
  if (DirExists(path)) return true;
  std::string cur;
  size_t i = 0;
  if (path[0] == '/') { cur = "/"; i = 1; }
  while (i <= path.size()) {
    size_t j = path.find('/', i);
    if (j == std::string::npos) j = path.size();
    if (j > i) {
      if (cur.size() && cur[cur.size() - 1] != '/') cur += '/';
      cur.append(path, i, j - i);
      if (!DirExists(cur)) {
        if (mkdir(cur.c_str(), 0777) != 0 && !DirExists(cur)) return false;
      }
    }
    if (j == path.size()) break;
    i = j + 1;
  }
  return true;
}

bool RemoveFileOrDir(const std::string &path) {
  if (DirExists(path)) return rmdir(path.c_str()) == 0;
  return unlink(path.c_str()) == 0;
}

bool RenamePath(const std::string &from, const std::string &to) {
  return rename(from.c_str(), to.c_str()) == 0;
}

bool FileExists(const std::string &path) {
  struct stat st;
  return lstat(path.c_str(), &st) == 0;
}

bool DirExists(const std::string &path) {
  struct stat st;
  if (stat(path.c_str(), &st) != 0) return false;
  return S_ISDIR(st.st_mode) != 0;
}

bool SetFileModTimes(const std::string &path, bool hasM, UInt64 mtime, bool hasA, UInt64 atime) {
  struct timespec ts[2];
  Int64 sec; long nsec;
  if (hasA) { FileTimeToUnix(atime, sec, nsec); ts[0].tv_sec = (time_t)sec; ts[0].tv_nsec = nsec; }
  else { ts[0].tv_sec = 0; ts[0].tv_nsec = UTIME_OMIT; }
  if (hasM) { FileTimeToUnix(mtime, sec, nsec); ts[1].tv_sec = (time_t)sec; ts[1].tv_nsec = nsec; }
  else { ts[1].tv_sec = 0; ts[1].tv_nsec = UTIME_OMIT; }
  return utimensat(AT_FDCWD, path.c_str(), ts, AT_SYMLINK_NOFOLLOW) == 0;
}

bool SetFileMode(const std::string &path, UInt32 mode) {
  return chmod(path.c_str(), (mode_t)(mode & 07777)) == 0;
}

bool CreateSymLink(const std::string &target, const std::string &path) {
  unlink(path.c_str());
  return symlink(target.c_str(), path.c_str()) == 0;
}

bool CreateHardLink(const std::string &target, const std::string &path) {
  unlink(path.c_str());
  return link(target.c_str(), path.c_str()) == 0;
}

std::string GetCurrentDirPath() {
  char buf[4096];
  if (getcwd(buf, sizeof(buf))) return std::string(buf);
  return std::string(".");
}

std::string GetTempDirPath() {
  const char *t = getenv("TMPDIR");
  if (t && *t) return std::string(t);
  return std::string("/tmp");
}

// ---------------------------------------------------------------------- paths

std::string PathJoin(const std::string &a, const std::string &b) {
  if (a.empty()) return b;
  if (b.empty()) return a;
  if (a[a.size() - 1] == '/') return a + b;
  return a + "/" + b;
}

void SplitPath(const std::string &path, std::string &dir, std::string &name) {
  size_t p = path.rfind('/');
  if (p == std::string::npos) { dir.clear(); name = path; }
  else { dir = path.substr(0, p); name = path.substr(p + 1); }
}

std::string GetFileExtension(const std::string &name) {
  size_t slash = name.rfind('/');
  size_t dot = name.rfind('.');
  if (dot == std::string::npos) return std::string();
  if (slash != std::string::npos && dot < slash) return std::string();
  if (dot == 0 || (slash != std::string::npos && dot == slash + 1)) return std::string();
  return name.substr(dot + 1);
}

std::string RemoveExtension(const std::string &name) {
  size_t slash = name.rfind('/');
  size_t dot = name.rfind('.');
  if (dot == std::string::npos) return name;
  if (slash != std::string::npos && dot < slash) return name;
  if (dot == 0 || (slash != std::string::npos && dot == slash + 1)) return name;
  return name.substr(0, dot);
}

bool IsAbsolutePath(const std::string &p) { return !p.empty() && p[0] == '/'; }

std::string NormalizePath(const std::string &p) {
  std::string r;
  for (size_t i = 0; i < p.size(); i++) {
    if (p[i] == '/' && !r.empty() && r[r.size() - 1] == '/') continue;
    r += p[i];
  }
  while (r.size() >= 2 && r[0] == '.' && r[1] == '/') r.erase(0, 2);
  return r;
}

// ------------------------------------------------------------------ wildcards

static bool MatchCore(const char *pat, const char *s, bool cs, bool crossSlash) {
  for (;;) {
    char pc = *pat;
    if (pc == 0) return *s == 0;
    if (pc == '*') {
      pat++;
      // Collapse consecutive stars.
      while (*pat == '*') pat++;
      if (*pat == 0) {
        if (crossSlash) return true;
        return strchr(s, '/') == nullptr;
      }
